const data = $input.first().json;

// Get chunks returned by the Knowledge Retrieval Service
const chunks = data.chunks || [];

const formattedKnowledge = chunks.map((chunk, index) => {
  return `### Chunk ${index + 1}

Source: ${chunk.source_name}
Package: ${chunk.package_name}
Chunk Index: ${chunk.chunk_index}
Similarity Score: ${chunk.distance}

Content:
${chunk.content}`;
}).join("\n\n==================================================\n\n");

// Return clean context for the AI Agent
return [
  {
    json: {
      userRequest: $('When Executed by Another Workflow').first().json.userRequest,
      knowledge: formattedKnowledge,
      chunkCount: chunks.length
    }
  }
];
